 * Function: Retrieve a customer's purchase history with product details.
 * 
 * @param customer_id ID of the customer to query
 * @return List of purchase history items
 */
std::vector<PurchaseHistory> query_customer_purchase_history(int customer_id) {
  using namespace sqlgen;

  // Connect to database
  auto conn = sqlite::connect("test_db.sqlite").value();

  // Create tables if they don't exist
  conn = (create_table<Customer>{.if_not_exists_ = true})(conn).value();
  conn = (create_table<Product>{.if_not_exists_ = true})(conn).value();
  conn = (create_table<Order>{.if_not_exists_ = true})(conn).value();
  conn = (create_table<OrderItem>{.if_not_exists_ = true})(conn).value();

  // Build and execute query
  auto result = select_from<Customer, "c">(
      col<"p", "name"> | as<"product_name">,
      col<"o", "order_date"> | as<"order_date">,
      col<"oi", "quantity"> | as<"quantity">
    )
    | inner_join<Order, "o">(col<"c", "customer_id"> == col<"o", "customer_id">)
    | inner_join<OrderItem, "oi">(col<"o", "order_id"> == col<"oi", "order_id">)
    | inner_join<Product, "p">(col<"oi", "product_id"> == col<"p", "product_id">)
    | where(col<"c", "customer_id"> == customer_id)
    | order_by(col<"o", "order_date">.desc())
    | to<std::vector<PurchaseHistory>>();

  return result(conn).value();
}

