#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace transaction_transfer_funds {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
};

bool transfer_funds(int from_account_id, int to_account_id, double amount) {
  using namespace sqlgen;

  // Connect to the SQLite database
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }

  // Begin transaction
  auto trans_result = begin_transaction(conn_result);
  if (!trans_result) {
    return false;
  }

  // Read from_account to verify sufficient funds
  auto from_account_result = 
      read<Account> | where(&Account::account_id == from_account_id) 
      | trans_result;

  if (!from_account_result) {
    rollback(trans_result);
    return false;
  }

  // Check if balance is sufficient
  if (from_account_result->balance < amount) {
    rollback(trans_result);
    return false;
  }

  // Update from_account: deduct amount
  auto update1_result = 
      update<Account>(set(&Account::balance, &Account::balance - amount))
      | where(&Account::account_id == from_account_id)
      | trans_result;

  if (!update1_result) {
    rollback(trans_result);
    return false;
  }

  // Update to_account: add amount
  auto update2_result =
      update<Account>(set(&Account::balance, &Account::balance + amount))
      | where(&Account::account_id == to_account_id)
      | update1_result;

  if (!update2_result) {
    rollback(update1_result);
    return false;
  }

  // Commit transaction
  auto commit_result = commit(update2_result);
  if (!commit_result) {
    rollback(update2_result);
    return false;
  }

  return true;
}

}  // namespace transaction_transfer_funds
