// update_eas_table.hpp
#pragma once

#include <filesystem>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

#include "eas_common.hpp"

namespace update_eas_table {

void update_eas_table() {
  design_eas_database_with_major();

  sqlgen::sqlite::connect(db_path)
      .and_then([](auto&& conn) {
        // 1. Add Grade column to Score table with type CHAR(1), NOT NULL
        return sqlgen::exec(conn, "ALTER TABLE Score ADD COLUMN Grade CHAR(1) NOT NULL DEFAULT 'A';");
      })
      .and_then([](auto&& conn) {
        // 2. Modify/Add Age column in Student table to type INT, allowing NULL
        // Note: SQLite has limited ALTER COLUMN support, so we ADD the column if it doesn't exist
        // or this assumes it's being modified from a different type
        return sqlgen::exec(conn, "ALTER TABLE Student ADD COLUMN Age INT;");
      })
      .and_then(sqlgen::drop<Major>)  // 3. Drop the Major table
      .value();
}

} // namespace update_eas_table
```

**Note:** I added a DEFAULT value for the `Grade` column because SQLite requires a default value when adding a NOT NULL column to an existing table that may have rows. For the `Age` column, since it's specified to allow NULL values and the column doesn't exist in the original `Student` struct, I'm adding it as a nullable INT column.

