#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace schema_create_view_sales_summary {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
  int stock;
};

struct Sale {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct SalesSummary {
  static constexpr bool is_view = true;
  std::string product_name;
  int total_quantity;
  double total_revenue;
};

/**
 * Function: Create a view SalesSummary that aggregates sales by product.
 * 
 * @return true if view creation succeeds, false otherwise
 */
bool create_view_sales_summary() {
  // Connect to the SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }

  // Build the SELECT query for the view
  // SELECT p.name as product_name, SUM(s.quantity) as total_quantity, SUM(s.amount) as total_revenue
  // FROM Sale s
  // JOIN Product p ON s.product_id = p.product_id
  // GROUP BY p.name
  auto query = sqlgen::select_from<Sale, "s">(
    sqlgen::col<"p", "name">.as<"product_name">(),
    sqlgen::sum(sqlgen::col<"s", "quantity">).as<"total_quantity">(),
    sqlgen::sum(sqlgen::col<"s", "amount">).as<"total_revenue">()
  )
  | sqlgen::inner_join<Product, "p">(
      sqlgen::col<"s", "product_id"> == sqlgen::col<"p", "product_id">
  )
  | sqlgen::group_by(sqlgen::col<"p", "name">);

  // Create the view with IF NOT EXISTS
  auto result = (sqlgen::create_as<SalesSummary>(query) | sqlgen::if_not_exists)(*conn_result);

  return result.has_value();
}

}  // namespace schema_create_view_sales_summary
