#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace calculate_order_metrics {

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  std::optional<double> discount_rate;
  std::optional<double> tax_rate;
};

struct OrderMetrics {
  int item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  double discount_rate;
  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

/**
 * Calculate per-item order metrics by loading the provided items into a temporary SQLite table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @param items Vector of OrderItem records to analyze.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl(const std::vector<OrderItem>& items) {
  // Connect to SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return {};
  }
  auto conn = *conn_result;

  // Create OrderItem table
  conn->execute(R"(
    CREATE TABLE IF NOT EXISTS OrderItem (
      item_id INTEGER PRIMARY KEY,
      order_id INTEGER NOT NULL,
      product_id INTEGER NOT NULL,
      unit_price REAL NOT NULL,
      quantity INTEGER NOT NULL,
      discount_rate REAL,
      tax_rate REAL
    )
  )");

  // Clear existing data
  conn->execute("DELETE FROM OrderItem");

  // Insert items into table
  for (const auto& item : items) {
    conn->write(item);
  }

  // Define column references
  const auto item_id = sqlgen::col<"item_id">;
  const auto order_id = sqlgen::col<"order_id">;
  const auto product_id = sqlgen::col<"product_id">;
  const auto unit_price = sqlgen::col<"unit_price">;
  const auto quantity = sqlgen::col<"quantity">;
  const auto discount_rate = sqlgen::col<"discount_rate">;
  const auto tax_rate = sqlgen::col<"tax_rate">;

  // Handle NULL values with COALESCE
  const auto discount_rate_safe = sqlgen::coalesce(discount_rate, 0.0);
  const auto tax_rate_safe = sqlgen::coalesce(tax_rate, 0.0);

  // Build query with arithmetic operations
  // Division, modulo, multiplication, addition, subtraction
  auto query_result = sqlgen::select_from<OrderItem>(
    item_id,
    order_id,
    product_id,
    unit_price,
    quantity,
    discount_rate_safe.as<"discount_rate">(),
    tax_rate_safe.as<"tax_rate">(),
    // Multiplication: unit_price * quantity
    (unit_price * quantity).as<"gross_total">(),
    // Subtraction and division: (1 - discount_rate/100)
    (unit_price * quantity * (1.0 - discount_rate_safe / 100.0)).as<"discounted_total">(),
    // Addition: (1 + tax_rate/100)
    (unit_price * quantity * (1.0 - discount_rate_safe / 100.0) * (1.0 + tax_rate_safe / 100.0)).as<"final_total">(),
    // Division: total / quantity
    (unit_price * quantity / quantity).as<"unit_cost">(),
    // Modulo: quantity % 10
    (quantity % 10).as<"quantity_group">(),
    // Multiplication: unit_price * 0.3
    (unit_price * 0.3).as<"estimated_profit">()
  ) | sqlgen::to<std::vector<OrderMetrics>>()
    | conn;

  if (!query_result) {
    return {};
  }

  return *query_result;
}

}  // namespace calculate_order_metrics
