  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Define columns for filtering
  constexpr auto bio = sqlgen::col<"bio">;
  constexpr auto avatar_url = sqlgen::col<"avatar_url">;

  // Read from Profile table where bio IS NULL OR avatar_url IS NULL
  // This filters rows with missing fields
  auto query = sqlgen::read<std::vector<Profile>> 
               | sqlgen::where(bio.is_null() || avatar_url.is_null());

  auto profiles_result = query(conn);

  // Convert to Result format
  std::vector<Result> results;
  if (profiles_result) {
    for (const auto& profile : profiles_result.value()) {
      results.push_back(Result{
        profile.profile_id.value(),
        profile.display_name
      });
    }
  }

  return results;
}

