    if (res.department_name.value_or("") == "Marketing") {
      found_marketing = true;
      EXPECT_FALSE(res.first_name.has_value());
      EXPECT_FALSE(res.last_name.has_value());
      EXPECT_FALSE(res.salary.has_value());
    }
  }
  EXPECT_TRUE(found_marketing);

