  std::vector<JoinResult> right_join_results;
  std::vector<JoinResult> full_join_results;
};

/**
 * analyze_department_employees
 * Provides data-join analysis between Department and Employee input collections by
 * creating temporary SQL tables, inserting the provided rows, and executing a
 * variety of join queries to produce join-output samples.
 * Returns: JoinAnalysis.
 */
JoinAnalysis analyze_department_employees_impl(const std::vector<Department>& depts, const std::vector<Employee>& emps) {
  JoinAnalysis analysis;

  // Connect to the SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return analysis; // Return empty analysis on connection failure
  }

  auto conn = std::move(*conn_result);

  // Drop existing tables if they exist to ensure clean state
  conn->execute("DROP TABLE IF EXISTS Employee");
  conn->execute("DROP TABLE IF EXISTS Department");

  // Create tables
  conn->create_table<Department>();
  conn->create_table<Employee>();

  // Insert department data
  for (const auto& dept : depts) {
    conn->write(dept);
  }

  // Insert employee data
  for (const auto& emp : emps) {
    conn->write(emp);
  }

  // INNER JOIN: Get employees with assigned departments
  auto inner_query = R"(
    SELECT d.department_name, e.first_name, e.last_name, e.salary
    FROM Department d
    INNER JOIN Employee e ON d.department_id = e.department_id
  )";
  auto inner_result = conn->template execute<std::vector<JoinResult>>(inner_query);
  if (inner_result) {
    analysis.inner_join_results = std::move(*inner_result);
  }

  // LEFT JOIN: Include all employees (even without departments)
  auto left_query = R"(
    SELECT d.department_name, e.first_name, e.last_name, e.salary
    FROM Employee e
    LEFT JOIN Department d ON e.department_id = d.department_id
  )";
  auto left_result = conn->template execute<std::vector<JoinResult>>(left_query);
  if (left_result) {
    analysis.left_join_results = std::move(*left_result);
  }

  // RIGHT JOIN: Include all departments (even without employees)
  // Note: SQLite doesn't support RIGHT JOIN, so we use LEFT JOIN with reversed tables
  auto right_query = R"(
    SELECT d.department_name, e.first_name, e.last_name, e.salary
    FROM Department d
    LEFT JOIN Employee e ON d.department_id = e.department_id
  )";
  auto right_result = conn->template execute<std::vector<JoinResult>>(right_query);
  if (right_result) {
    analysis.right_join_results = std::move(*right_result);
  }

  // FULL JOIN: Include all employees and departments
  // Note: SQLite doesn't support FULL JOIN natively, so we use UNION of LEFT JOINs
  auto full_query = R"(
    SELECT d.department_name, e.first_name, e.last_name, e.salary
    FROM Department d
    LEFT JOIN Employee e ON d.department_id = e.department_id
    UNION
    SELECT d.department_name, e.first_name, e.last_name, e.salary
    FROM Employee e
    LEFT JOIN Department d ON e.department_id = d.department_id
    WHERE d.department_name IS NULL
  )";
  auto full_result = conn->template execute<std::vector<JoinResult>>(full_query);
  if (full_result) {
    analysis.full_join_results = std::move(*full_result);
  }

  return analysis;
}

}  // namespace analyze_department_employees
