std::string create_as_to_sql(const dynamic::CreateAs& _stmt) noexcept {
  std::stringstream stream;

  stream << "CREATE "
         << internal::strings::replace_all(
                internal::strings::to_upper(rfl::enum_to_string(_stmt.what)),
                "_", " ")
         << " ";

  if (_stmt.if_not_exists) {
