  if (_stmt.table_or_view.schema) {
    stream << wrap_in_quotes(*_stmt.table_or_view.schema) << ".";
  }
  stream << wrap_in_quotes(_stmt.table_or_view.name) << " AS ";

  stream << select_from_to_sql(_stmt.query);

