namespace get_top_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string product_name;
  std::string category;
  double price;
};

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Date sale_date;
};

struct TopProduct {
  int product_id;
  std::string product_name;
  std::string category;
  double total_sales;
};

/**
 * Description: This function retrieves the top products based on total sales.
 * Returns: std::vector<TopProduct>.
 */
std::vector<TopProduct> get_top_products(size_t limit_count = 10) {
  // Connect to the SQLite database
  auto db = sqlgen::sqlite::connect("test_db.sqlite");

  // Define table references
  auto p = sqlgen::table<Product>("Product");
  auto s = sqlgen::table<Sales>("Sales");

  // Build the query with join, aggregation, grouping, ordering, and limit
  auto query = sqlgen::select(
    p.product_id,
    p.product_name,
    p.category,
    sqlgen::sum(p.price * s.quantity).as("total_sales")
  )
  .from(p)
  .inner_join(s).on(p.product_id == s.product_id)
  .group_by(p.product_id, p.product_name, p.category)
  .order_by(sqlgen::desc("total_sales"))
  .limit(limit_count);

  // Execute the query and collect results
  std::vector<TopProduct> results;
  auto result_set = db.execute(query);

  for (auto& row : result_set) {
    TopProduct tp;
    tp.product_id = row.get<int>(0);
    tp.product_name = row.get<std::string>(1);
    tp.category = row.get<std::string>(2);
    tp.total_sales = row.get<double>(3);
    results.push_back(tp);
  }

  return results;
}

}  // namespace get_top_products
